import{_ as l,C as o,o as d,c,j as t,a,E as s,a8 as p}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/eskgvQYchd0-640.webp",w="/schedule-dashboard/thumbs/yt/eskgvQYchd0-1280.webp",n="/schedule-dashboard/thumbs/yt/1NXUw8QK1L4-640.webp",u="/schedule-dashboard/thumbs/yt/1NXUw8QK1L4-1280.webp",Q=JSON.parse('{"title":"AI Digest · Fri 16 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-16","routine":"digest"},"relativePath":"digest/2026-10-16.md","filePath":"digest/[date].md"}'),m={name:"digest/2026-10-16.md"},g=r+" 640w, "+w+" 1280w",v=n+" 640w, "+u+" 1280w",b={id:"ai-digest-·-fri-16-oct-2026",tabindex:"-1"};function f(y,e,k,_,N,A){const i=o("Badge"),h=o("DayFilter");return d(),c("div",null,[t("h1",b,[e[0]||(e[0]=a("AI Digest · Fri 16 Oct 2026 ",-1)),s(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-fri-16-oct-2026","aria-label":'Permalink to "AI Digest · Fri 16 Oct 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (16 Oct 2026) · run date Fri 16 Oct 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"Better Stack"),a(" posted 2 full videos (about 17.7 minutes). The freshest is Josh's Phonon-2 speech-model review (164MB English STT vs Whisper/Redux, with a useful vendor-benchmark skepticism). The other is a Voyager 1 remote-patching story — dead chip, hand binary, thrusters revived after 21 years. No AI Engineer uploads in the window.")])],-1)),s(h),e[5]||(e[5]=p('<div class="grid cards2"><article class="it full" id="v-eskgvQYchd0" data-title="This 164MB Speech Model Might Replace Whisper..." data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=eskgvQYchd0" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=eskgvQYchd0" target="_blank" rel="noopener">This 164MB Speech Model Might Replace Whisper...</a></h3><div class="meta">Better Stack · Josh, Better Stack · uploaded 15 Oct, 8:30 PM IST · 9:28</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — another tiny-STT review, but the Fluid Audio / vendor-vs-Open-ASR skepticism is the useful takeaway; treat Phonon as an experiment on Apple Silicon English audio, not a Redux replacement yet.</div><div class="repeat">🔁 Repeat: &#39;voice / speech models&#39; — seen 8 times before. New here: Fermion Phonon-2 vs Parakeet Redux/Whisper, with a Fluid Audio port critique and independent Open ASR leaderboard numbers.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 38 times before. New here: 164MB English-only retrain of the same Nvidia Parakeet base Redux compressed (1.58-bit) differently.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 34 times before. New here: vendor WER numbers vs Open ASR leaderboard (Phonon 7.23 vs Whisper Turbo 8.39) and why the &quot;6× faster than Redux&quot; claim is shaky.</div><div class="sh">What Phonon-2 is</div><ul><li><strong>164MB, English-first:</strong> Fermion Research (~6 weeks old) starts from Nvidia&#39;s ~2.5GB Parakeet and retrains the encoder so every weight is one of five learned values (~2.1 bits) with 6-bit tables; download is 164MB (expands ~178MB), same ballpark as Moondream&#39;s Parakeet Redux but Redux spreads capacity across 25 languages while Phonon focuses on English (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=96s" target="_blank" rel="noopener">1:36</a>)</li><li><strong>Install and claimed speed:</strong> Python 3.10+, `pip` Fermion with the MLX extra, then `phonon transcribe` on a file. Fermion claims 174× realtime on a 16GB M5 MacBook Air (1 hour → ~21s) with the default fast-path decoder; exact decode ~109×, CPU-only ~40×; their table puts Whisper Large V3 Turbo via whisper.cpp+Metal at ~17× (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=96s" target="_blank" rel="noopener">1:36</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=194s" target="_blank" rel="noopener">3:14</a>)</li></ul><div class="sh">Accuracy and the benchmark catch</div><ul><li><strong>Vendor WERs:</strong> Fermion&#39;s seven-set average: Phonon 5.21, Redux 5.69, Whisper Turbo 6.58, full Nvidia Parakeet 4.96 — so the 164MB model is within ~0.25 of a model ~15× larger; they call it the most accurate open English STT under 900MB. Redux&#39;s own card reported 6.55 average (different method), and even in Fermion&#39;s table Redux wins AMI (9.16 vs 9.37) (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=194s" target="_blank" rel="noopener">3:14</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=280s" target="_blank" rel="noopener">4:40</a>)</li><li><strong>&quot;6× faster than Redux&quot; is misleading:</strong> Fermion timed Redux via a third-party Core ML port (Fluid Audio) at only 27.8×, while the much larger original Nvidia model hit 105× through that same port — a sign the port, not Redux, is slow. Moondream reports Redux at 38–43× on an older M2 Air (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=280s" target="_blank" rel="noopener">4:40</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=325s" target="_blank" rel="noopener">5:25</a>)</li><li><strong>Independent Open ASR leaderboard (2 Oct):</strong> Phonon averaged 7.23 vs Nvidia 6.51 and Whisper Turbo 8.39; Whisper still wins three sets (e.g. Urgent 2024 noisy speech 13.69 vs Phonon&#39;s 14.90). Redux isn&#39;t on the board, so no independent tiny-vs-tiny head-to-head (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=325s" target="_blank" rel="noopener">5:25</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=380s" target="_blank" rel="noopener">6:20</a>)</li></ul><div class="sh">Dev features and license</div><ul><li><strong>Live captions, hotwords, local OpenAI-compatible API:</strong> `phonon listen` for mic captions; pass a hotword list for names/jargon; `phonon serve` on port 8000 exposes an OpenAI-compatible transcription endpoint plus WebSocket — point an existing OpenAI STT client at localhost. Streaming latency not measured here; underlying model is offline (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=380s" target="_blank" rel="noopener">6:20</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>License OK for commercial use:</strong> Code/CLI Apache 2.0; weights CC BY 4.0 (inherited from Nvidia) with attribution to Nvidia and Fermion. Project is new; main real-world user so far is Fermion&#39;s own Mac dictation app (<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=eskgvQYchd0&amp;t=529s" target="_blank" rel="noopener">8:49</a>)</li></ul></div></article><article class="it full" id="v-1NXUw8QK1L4" data-title="How NASA Patch Voyager 1 From 16 Billion Miles Away" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=1NXUw8QK1L4" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+v+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=1NXUw8QK1L4" target="_blank" rel="noopener">How NASA Patch Voyager 1 From 16 Billion Miles Away</a></h3><div class="meta">Better Stack · Better Stack · uploaded 15 Oct, 2:25 PM IST · 8:15</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — concrete remote-patching story (dead chip, hand binary, no simulator) and the 21-year thruster recovery; short and specific.</div><div class="sh">One light-day out</div><ul><li><strong>18 Nov milestone:</strong> Voyager 1 will be one light-day from Earth (~25.9 billion km / 16 billion miles) — a command takes a full day each way. Still on the 1977 computers with under 70KB of memory across the set, and NASA is still patching it (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=87s" target="_blank" rel="noopener">1:27</a>)</li><li><strong>Three computers + spares:</strong> One runs commands and watches for faults, one keeps the antenna pointed at Earth, one packs and sends data; each has a spare. All six together ≈69KB (&quot;small potatoes&quot; per NASA&#39;s FAQ). Written in assembly; the pointing computer launched with two words free. Unlike Apollo&#39;s woven ROM, Voyager memory is rewritable — 18 programs uploaded during the 1979 Jupiter flyby (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=87s" target="_blank" rel="noopener">1:27</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=171s" target="_blank" rel="noopener">2:51</a>)</li></ul><div class="sh">The dead chip (Nov 2023–Jun 2024)</div><ul><li><strong>Garbage telemetry:</strong> On 14 Nov 2023 the data computer still executed commands but returned repeating ones-and-zeros. A March 2024 &quot;poke&quot; made it dump its full memory two days later; by April the team found one chip dead and ~3% of memory corrupted (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=171s" target="_blank" rel="noopener">2:51</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=227s" target="_blank" rel="noopener">3:47</a>)</li><li><strong>Hand-binary patch, no test machine:</strong> The chip held one bit of each of 256 sixteen-bit words, so all 256 were broken and held shared routines. No single free gap fit them, so the team split the code into scrap gaps and retargeted every caller — translated to binary by hand with no assembler and no ground test rig (&quot;first time they&#39;d loaded flight software without thoroughly testing on the ground&quot;). Engineering data restored 18 Apr 2024; science data by May–June (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=227s" target="_blank" rel="noopener">3:47</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=311s" target="_blank" rel="noopener">5:11</a>)</li></ul><div class="sh">Thrusters, power, where it is</div><ul><li><strong>Thrusters &quot;dead&quot; since 2004 revived:</strong> Fuel tubes clogging (0.25mm → ~0.035mm from SiO₂ shed by rubber in the tank). Main roll thrusters lost heaters in 2004 and were written off; backups were clogging too, and Canberra&#39;s 70m dish (only one strong enough to command Voyager) was due offline May 2025–Feb 2026. On 20 Mar 2025 a gamble that heaters were fine and a switch had glitched paid off within ~20 minutes after 21 years (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=311s" target="_blank" rel="noopener">5:11</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=393s" target="_blank" rel="noopener">6:33</a>)</li><li><strong>Power budget and Horizons:</strong> Plutonium loses ~4W/year; 8 of 10 instruments are already off; NASA expects at least one instrument into the 2030s and dish contact until ~2036. JPL Horizons (target -31) via a curl shows one-way light time just under 1,440 minutes now, past exactly 24h on 18 Nov — and the delay shrinks a couple of minutes when Earth laps it (<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=393s" target="_blank" rel="noopener">6:33</a>–<a href="https://www.youtube.com/watch?v=1NXUw8QK1L4&amp;t=495s" target="_blank" rel="noopener">8:15</a>)</li></ul></div></article></div>',1))])}const S=l(m,[["render",f]]);export{Q as __pageData,S as default};
